package assetsbridge

import (
	"bytes"
	"encoding/hex"
	"errors"
	"fmt"
	"math/big"

	"github.com/btcsuite/btcd/txscript"
	"github.com/btcsuite/btcd/wire"
	sdk "github.com/cosmos/cosmos-sdk/types"
	banktypes "github.com/cosmos/cosmos-sdk/x/bank/types"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/tracing"
	"github.com/holiman/uint256"
	"github.com/mezo-org/mezod/precompile"
	"github.com/mezo-org/mezod/x/evm/statedb"
	evmtypes "github.com/mezo-org/mezod/x/evm/types"
)

// BridgeOutMethodName is the name of the bridgeOut method.
// It matches the name of the method in the contract ABI.
//
//nolint:gosec
const BridgeOutMethodName = "bridgeOut"

// SendMsgURL defines the authorization type for MsgSend
var SendMsgURL = sdk.MsgTypeURL(&banktypes.MsgSend{})

// BridgeOutMethod is the implementation of the bridgeOut method.
type BridgeOutMethod struct {
	bridgeKeeper BridgeKeeper
	authzKeeper  AuthzKeeper
}

func newBridgeOutMethod(
	bridgeKeeper BridgeKeeper,
	authzKeeper AuthzKeeper,
) *BridgeOutMethod {
	return &BridgeOutMethod{
		bridgeKeeper: bridgeKeeper,
		authzKeeper:  authzKeeper,
	}
}

func (m *BridgeOutMethod) MethodName() string {
	return BridgeOutMethodName
}

func (m *BridgeOutMethod) MethodType() precompile.MethodType {
	return precompile.Write
}

func (m *BridgeOutMethod) RequiredGas(_ []byte) (uint64, bool) {
	// Fallback to the default gas calculation.
	return 0, false
}

func (m *BridgeOutMethod) Payable() bool {
	return false
}

func (m *BridgeOutMethod) Run(
	context *precompile.RunContext,
	rawInputs precompile.MethodInputs,
) (precompile.MethodOutputs, []statedb.StateChange, error) {
	inputs, err := m.extractInputs(rawInputs)
	if err != nil {
		return precompile.MethodOutputs{false}, nil, err
	}

	if err := m.validate(context, inputs); err != nil {
		return precompile.MethodOutputs{false}, nil, err
	}

	return m.execute(context, inputs)
}

// execute will execute the burn of the token then send
// AssetsUnlocked events to the bridgeKeeper.
func (m *BridgeOutMethod) execute(
	context *precompile.RunContext,
	inputs *bridgeOutInputs,
) (precompile.MethodOutputs, []statedb.StateChange, error) {
	var (
		err   error
		isBTC = bytes.Equal(
			common.HexToAddress(evmtypes.BTCTokenPrecompileAddress).Bytes(),
			inputs.Token.Bytes(),
		)
	)

	sdkAmount, err := precompile.TypesConverter.BigInt.ToSDK(inputs.Amount)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to convert amount: [%w]", err)
	}
	assetsUnlocked, err := m.bridgeKeeper.SaveAssetsUnlocked(
		context.SdkCtx(),
		inputs.Recipient,
		inputs.Token.Bytes(),
		context.MsgSender().Bytes(),
		sdkAmount,
		uint8(inputs.Chain),
	)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to send AssetsUnlocked to bridge: %w", err)
	}

	err = context.EventEmitter().Emit(
		NewAssetsUnlockedEvent(
			assetsUnlocked.UnlockSequence.BigInt(),
			assetsUnlocked.Recipient,
			common.HexToAddress(assetsUnlocked.Token),
			context.MsgSender(),
			assetsUnlocked.Amount.BigInt(),
			uint8(assetsUnlocked.Chain), //nolint:gosec // G115: Safe conversion, Chain is validated elsewhere
		),
	)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to emit AssetsUnlocked event: [%w]", err)
	}

	var changes []statedb.StateChange

	switch inputs.Chain {
	case TargetChainEthereum:
		if isBTC {
			err = m.burnBitcoin(context, inputs)
		} else {
			changes, err = m.burnERC20(context, inputs)
		}
	case TargetChainBitcoin:
		err = m.burnBitcoin(context, inputs)
	default:
		panic(fmt.Sprintf("unreachable, unsupported target chain: %v", inputs.Chain))
	}

	return precompile.MethodOutputs{err == nil}, changes, err
}

func (m *BridgeOutMethod) burnERC20(
	context *precompile.RunContext,
	inputs *bridgeOutInputs,
) ([]statedb.StateChange, error) {
	var (
		sdkCtx   = context.SdkCtx()
		fromAddr = context.MsgSender()
	)

	return m.bridgeKeeper.BurnERC20(
		sdkCtx, inputs.Token.Bytes(), fromAddr.Bytes(), inputs.Amount)
}

func (m *BridgeOutMethod) burnBitcoin(
	context *precompile.RunContext,
	inputs *bridgeOutInputs,
) error {
	bridgeAddr := sdk.AccAddress(common.HexToAddress(
		evmtypes.AssetsBridgePrecompileAddress,
	).Bytes())
	senderAddr := sdk.AccAddress(context.MsgSender().Bytes())

	authorization, expiration := m.authzKeeper.GetAuthorization(
		context.SdkCtx(), bridgeAddr.Bytes(), senderAddr.Bytes(), SendMsgURL,
	)
	if authorization == nil {
		return fmt.Errorf("%s authorization type does not exist or is expired for address %s", SendMsgURL, senderAddr)
	}

	sendAuth, ok := authorization.(*banktypes.SendAuthorization)
	if !ok {
		return fmt.Errorf(
			"expected authorization to be a %T", banktypes.SendAuthorization{},
		)
	}

	sdkAmount, err := precompile.TypesConverter.BigInt.ToSDK(inputs.Amount)
	if err != nil {
		return fmt.Errorf("failed to convert amount: [%w]", err)
	}
	coin := sdk.Coin{Denom: evmtypes.DefaultEVMDenom, Amount: sdkAmount}

	// now update the authorization to spend for the AssetsBridge
	msg := banktypes.NewMsgSend(senderAddr.Bytes(), bridgeAddr.Bytes(), sdk.NewCoins(coin))
	resp, err := sendAuth.Accept(context.SdkCtx(), msg)
	if err != nil {
		return fmt.Errorf("couldn't accept authorization: %w", err)
	}

	if resp.Delete {
		// Authorization fully consumed, delete it
		err = m.authzKeeper.DeleteGrant(context.SdkCtx(), bridgeAddr, senderAddr, SendMsgURL)
	} else if resp.Updated != nil {
		err = m.authzKeeper.SaveGrant(context.SdkCtx(), bridgeAddr, senderAddr, resp.Updated, expiration)
	}
	if err != nil {
		return fmt.Errorf("couldn't update authorization BTC: %w", err)
	}

	if !resp.Accept {
		return errors.New("bridge is not authorized to burn BTC")
	}

	if err := m.bridgeKeeper.BurnBTC(
		context.SdkCtx(),
		senderAddr.Bytes(),
		sdkAmount,
	); err != nil {
		return fmt.Errorf("couldn't burn BTC: %w", err)
	}

	// finally update the journal entries to propagate the changes
	// done to the gas token (BTC in our case)
	balanceDelta, overflow := uint256.FromBig(inputs.Amount)
	if overflow {
		return fmt.Errorf("conversion from big.Int to uint256.Int overflowed: %v", inputs.Amount)
	}

	// only one side of the transfer to update here as we
	// burnt funds
	journal := context.Journal()
	journal.SubBalance(common.BytesToAddress(senderAddr.Bytes()), balanceDelta, tracing.BalanceChangeTransfer)

	return nil
}

// validate applies more extensive validation to the inputs, not only
// the semantic validation but also verify balances, and tokens etc.
func (m *BridgeOutMethod) validate(
	context *precompile.RunContext,
	inputs *bridgeOutInputs,
) error {
	sdkCtx := context.SdkCtx()

	if inputs.Amount == nil {
		return errors.New("amount is required")
	}

	if inputs.Amount.Sign() <= 0 {
		return errors.New("amount must be positive")
	}

	if err := m.validateAmount(sdkCtx, inputs.Amount, inputs.Token, inputs.Chain); err != nil {
		return err
	}

	_, ok := inputs.Chain.Validate()
	if !ok {
		return fmt.Errorf("unsupported chain: %v", inputs.Chain)
	}

	if err := m.validateRecipientForChain(inputs.Chain, inputs.Recipient); err != nil {
		return err
	}

	// first check that the token is either BTC or a supported ERC20
	if err := m.validateToken(sdkCtx, inputs.Token, inputs.Chain); err != nil {
		return err
	}

	return nil
}

func (m *BridgeOutMethod) validateToken(
	sdkCtx sdk.Context,
	token common.Address,
	chain TargetChain,
) error {
	btcToken := common.HexToAddress(evmtypes.BTCTokenPrecompileAddress)
	if bytes.Equal(btcToken.Bytes(), token.Bytes()) {
		return nil
	}

	switch chain {
	case TargetChainEthereum:
		if _, ok := m.bridgeKeeper.GetERC20TokenMappingFromMezoToken(sdkCtx, token.Bytes()); ok {
			return nil
		}

		return fmt.Errorf("unsupported token: %v for ethereum target chain", token)
	case TargetChainBitcoin:
		return fmt.Errorf("unsupported token: %v for bitcoin target chain", token)
	default:
		panic("unreachable: unknown chain type")
	}
}

func (m *BridgeOutMethod) validateAmount(
	sdkCtx sdk.Context,
	amount *big.Int,
	token common.Address,
	chain TargetChain,
) error {
	sdkAmount, err := precompile.TypesConverter.BigInt.ToSDK(amount)
	if err != nil {
		return fmt.Errorf("failed to convert amount: [%w]", err)
	}

	if chain == TargetChainBitcoin {
		// For Bitcoin chain, first check Bitcoin-specific minimum. If it is not set,
		// use the general minimum.
		bitcoinMinAmount := m.bridgeKeeper.GetMinBridgeOutAmountForBitcoinChain(sdkCtx)
		if !bitcoinMinAmount.IsZero() {
			if sdkAmount.LT(bitcoinMinAmount) {
				return fmt.Errorf(
					"amount below minimum bridgeable amount for Bitcoin chain: %s < %s",
					sdkAmount,
					bitcoinMinAmount,
				)
			}
			// Bitcoin-specific minimum is set and respected, we should not check the general minimum
			// so we return here.
			return nil
		}
	}

	minAmount := m.bridgeKeeper.GetMinBridgeOutAmount(
		sdkCtx,
		token.Bytes(),
	)

	if sdkAmount.LT(minAmount) {
		return fmt.Errorf(
			"amount below minimum bridgeable amount: %s < %s",
			sdkAmount,
			minAmount,
		)
	}

	return nil
}

// extractInputs extract the inputs from the precompile.MethodInputs and apply
// basic validation on the inputs
func (m *BridgeOutMethod) extractInputs(inputs precompile.MethodInputs) (*bridgeOutInputs, error) {
	if err := precompile.ValidateMethodInputsCount(inputs, 4); err != nil {
		return nil, err
	}

	token, ok := inputs[0].(common.Address)
	if !ok {
		return nil, fmt.Errorf("invalid token address: %v", inputs[0])
	}

	amount, ok := inputs[1].(*big.Int)
	if !ok {
		return nil, fmt.Errorf("invalid amount: %v", inputs[1])
	}

	chainRaw, ok := inputs[2].(uint8)
	if !ok {
		return nil, fmt.Errorf("invalid chain: %v", inputs[2])
	}

	chain := TargetChain(chainRaw)

	recipient, ok := inputs[3].([]byte)
	if !ok {
		return nil, fmt.Errorf("invalid recipient address: %v", inputs[3])
	}

	return &bridgeOutInputs{
		Token:     token,
		Amount:    amount,
		Chain:     chain,
		Recipient: recipient,
	}, nil
}

func (m *BridgeOutMethod) validateRecipientForChain(chain TargetChain, recipient []byte) error {
	if len(recipient) == 0 {
		return fmt.Errorf("recipient can't be empty")
	}

	switch chain {
	case TargetChainEthereum:
		// check the length and for the zero address
		if len(recipient) != 20 || bytes.Equal(recipient, (common.Address{}).Bytes()) {
			return fmt.Errorf("invalid recipient address for Ethereum chain: %v", hex.EncodeToString(recipient))
		}
	case TargetChainBitcoin:
		script, err := newScriptFromVarLenData(recipient)
		if err != nil {
			return fmt.Errorf("couldn't get script from var-len data: %v", err)
		}
		if !isSupportedBitcoinScriptType(script) {
			return fmt.Errorf("invalid recipient address for Bitcoin: %v", hex.EncodeToString(recipient))
		}
	}

	return nil
}

type TargetChain uint8

const (
	TargetChainEthereum = iota
	TargetChainBitcoin
)

func (t TargetChain) Validate() (TargetChain, bool) {
	if t == TargetChainEthereum || t == TargetChainBitcoin {
		return t, true
	}

	return t, false
}

type bridgeOutInputs struct {
	Token     common.Address
	Amount    *big.Int
	Chain     TargetChain
	Recipient []byte
}

// AssetsUnlockedEventName is the name of the AssetsUnlocked event. It matches the name
// of the event in the contract ABI.
const AssetsUnlockedEventName = "AssetsUnlocked"

// AssetsUnlockedEvent is the implementation of the AssetsUnlocked event that contains
// the following arguments:
// - unlockSequenceNumber (indexed): the sequenceNumber of this AssetsUnlocked
// - recipient (indexed): the address to which the tokens are transferred
// - token (indexed): the token being bridged out.
// - sender (non-indexed): the address from which the tokens are bridged out,
// - amount (non-indexed): the amount of tokens transferred
// - chain (non-indexed): the destination chain
type AssetsUnlockedEvent struct {
	unlockSequenceNumber *big.Int
	recipient            []byte
	token                common.Address
	sender               common.Address
	amount               *big.Int
	chain                uint8
}

func NewAssetsUnlockedEvent(
	sequenceNumber *big.Int,
	recipient []byte,
	token common.Address,
	sender common.Address,
	amount *big.Int,
	chain uint8,
) *AssetsUnlockedEvent {
	return &AssetsUnlockedEvent{
		unlockSequenceNumber: sequenceNumber,
		recipient:            recipient,
		token:                token,
		sender:               sender,
		amount:               amount,
		chain:                chain,
	}
}

func (te *AssetsUnlockedEvent) EventName() string {
	return AssetsUnlockedEventName
}

func (te *AssetsUnlockedEvent) Arguments() []*precompile.EventArgument {
	return []*precompile.EventArgument{
		{
			Indexed: true,
			Value:   te.unlockSequenceNumber,
		},
		{
			Indexed: true,
			Value:   te.recipient,
		},
		{
			Indexed: true,
			Value:   te.token,
		},
		{
			Indexed: false,
			Value:   te.sender,
		},
		{
			Indexed: false,
			Value:   te.amount,
		},
		{
			Indexed: false,
			Value:   te.chain,
		},
	}
}

func isSupportedBitcoinScriptType(script []byte) bool {
	switch txscript.GetScriptClass(script) {
	case txscript.PubKeyHashTy, txscript.WitnessV0PubKeyHashTy,
		txscript.ScriptHashTy, txscript.WitnessV0ScriptHashTy:
		return true
	default:
		return false
	}
}

// NewScriptFromVarLenData construct a Script instance based on the provided
// variable length data prepended with a CompactSizeUint.
func newScriptFromVarLenData(varLenData []byte) ([]byte, error) {
	// Extract the CompactSizeUint value that holds the byte length of the script.
	// Also, extract the byte length of the CompactSizeUint itself.
	scriptByteLength, compactByteLength, err := readCompactSizeUint(varLenData)
	if err != nil {
		return nil, fmt.Errorf("cannot read compact size uint: [%v]", err)
	}

	// Make sure the combined byte length of the script and the byte length
	// of the CompactSizeUint matches the total byte length of the variable
	// length data. Otherwise, the input data slice is malformed.
	//nolint:gosec
	if scriptByteLength+uint64(compactByteLength) != uint64(len(varLenData)) {
		return nil, fmt.Errorf("malformed var len data")
	}

	// Extract the actual script by omitting the leading CompactSizeUint.
	return varLenData[compactByteLength:], nil
}

// readCompactSizeUint reads the leading CompactSizeUint from the provided
// variable length data. Returns the value held by the CompactSizeUint as
// the first argument and the byte length of the CompactSizeUint as the
// second one.
func readCompactSizeUint(varLenData []byte) (uint64, int, error) {
	csu, err := wire.ReadVarInt(bytes.NewReader(varLenData), 0)
	if err != nil {
		return 0, 0, err
	}

	return csu, wire.VarIntSerializeSize(csu), nil
}

x/bridge/keeper/assets_locked.go.content:
package keeper

import (
	"bytes"
	"fmt"

	authtypes "github.com/cosmos/cosmos-sdk/x/auth/types"

	"cosmossdk.io/math"

	sdk "github.com/cosmos/cosmos-sdk/types"
	"github.com/mezo-org/mezod/x/bridge/types"
	evmtypes "github.com/mezo-org/mezod/x/evm/types"
)

// GetAssetsLockedSequenceTip returns the current sequence tip for the
// AssetsLocked events. The tip denotes the sequence number of the last event
// processed by the x/bridge module.
func (k Keeper) GetAssetsLockedSequenceTip(ctx sdk.Context) math.Int {
	bz := ctx.KVStore(k.storeKey).Get(types.AssetsLockedSequenceTipKey)
	if len(bz) == 0 {
		return math.ZeroInt()
	}

	sequenceTip := math.ZeroInt()
	if err := sequenceTip.Unmarshal(bz); err != nil {
		panic(err)
	}

	return sequenceTip
}

// SetAssetsLockedSequenceTip sets the current sequence tip for the AssetsLocked
// events. The tip denotes the sequence number of the last event processed by
// the x/bridge module.
func (k Keeper) setAssetsLockedSequenceTip(
	ctx sdk.Context,
	sequenceTip math.Int,
) {
	bz, err := sequenceTip.Marshal()
	if err != nil {
		panic(err)
	}

	ctx.KVStore(k.storeKey).Set(types.AssetsLockedSequenceTipKey, bz)
}

// AcceptAssetsLocked processes the given AssetsLocked events sequence by minting
// the corresponding amount of coins for each event and sending them to the
// recipient address.
//
// Requirements:
//  1. The AssetsLocked sequence must not be empty.
//  2. The AssetsLocked sequence must be valid (i.e. all events in the slice
//     pass the AssetsLockedEvent.IsValid test AND sequence numbers of events
//     form a sequence strictly increasing by 1).
//  3. The sequence number of the first event in the slice must be exactly one
//     greater than the current sequence tip held in the state.
//
// The function returns an error if any of the requirements is not met.
// Checking the mentioned requirements is crucial to ensure state consistency
// regardless of the guarantees provided by the upstream code.
//
// If all requirements are met and x/bank interactions are all successful, the
// current sequence tip in the state is updated to the sequence number of the
// last event in the slice.
func (k Keeper) AcceptAssetsLocked(
	ctx sdk.Context,
	events types.AssetsLockedEvents,
) error {
	if len(events) == 0 {
		return fmt.Errorf("empty AssetsLocked sequence")
	}

	if !events.IsValid() {
		return fmt.Errorf("invalid AssetsLocked sequence")
	}

	currentSequenceTip := k.GetAssetsLockedSequenceTip(ctx)
	expectedSequenceStart := currentSequenceTip.AddRaw(1)
	if sequenceStart := events[0].Sequence; !expectedSequenceStart.Equal(sequenceStart) {
		return fmt.Errorf(
			"unexpected AssetsLocked sequence start; expected %s, got %s",
			expectedSequenceStart,
			sequenceStart,
		)
	}

	sourceBTCToken := k.GetSourceBTCToken(ctx)

	for _, event := range events {
		recipient, err := sdk.AccAddressFromBech32(event.Recipient)
		if err != nil {
			return fmt.Errorf("failed to parse recipient address: %w", err)
		}

		// We need to ensure that the funds are not sent to a blocked address first.
		// In case the address is blocked, no minting should happen, and the funds should
		// remain locked in the bridge.
		if _, ok := k.blockedAddrs[recipient.String()]; ok {
			ctx.Logger().Warn(
				"deposit recipient is a blocked address; "+
					"AssetsLocked event skipped",
				"eventSequence", event.Sequence,
			)

			continue
		}

		// Intentionally not performing precompile address validation as we do
		// for the triparty bridging requests. We could add a check here, but this
		// check alone, without an accompanying mechanism in the `MezoBridge`
		// smart contract, would result in funds being locked in the bridge without
		// mint on the chain. This is expected behavior for blocked addresses, but
		// for all other addresses, we should either disallow locking funds or
		// allow locking and then minting. At the same time, we do not maintain
		// a list of blocked or precompile addresses in the `MezoBridge` smart
		// contract, as that would be a synchronization issue between chains,
		// and we only rely on information for blocked addresses as stored on Mezo.

		if bytes.Equal(event.TokenBytes(), sourceBTCToken) {
			err = k.mintBTC(ctx, recipient, event.Amount)
			if err != nil {
				return fmt.Errorf(
					"failed to mint BTC for event %v: %w",
					event.Sequence,
					err,
				)
			}
		} else {
			mapping, exists := k.GetERC20TokenMapping(ctx, event.TokenBytes())
			if !exists {
				// In case of a missing mapping, we skip the event and log a
				// warning. This is because we cannot mint ERC20 tokens without
				// a valid mapping. NOTE THAT THE SKIPPED EVENT WON'T BE
				// RE-PROCESSED SO FUNDS REMAIN LOCKED ON THE SOURCE CHAIN.
				ctx.Logger().Warn(
					"ERC20 mapping for source token not found; "+
						"AssetsLocked event skipped",
					"eventSequence", event.Sequence,
				)
				continue
			}

			err = k.mintERC20(
				ctx,
				recipient,
				mapping.MezoTokenBytes(),
				event.Amount,
			)
			if err != nil {
				// In case of an error, we skip the event and log a warning.
				// Unlike the BTC minting, we do not return an error here to
				// stop the consensus engine. This is because minting occurs on
				// external contracts, and we cannot guarantee that the minting
				// will always succeed. We cannot take a risk that one
				// malfunctioning contract will halt the whole chain.
				// NOTE THAT THE SKIPPED EVENT WON'T BE RE-PROCESSED SO FUNDS
				// REMAIN LOCKED ON THE SOURCE CHAIN.
				ctx.Logger().Error(
					"Encountered error while minting ERC20; "+
						"AssetsLocked event skipped",
					"eventSequence", event.Sequence,
					"error", err,
				)
				continue
			}
		}
	}

	k.setAssetsLockedSequenceTip(ctx, events[len(events)-1].Sequence)

	return nil
}

// mintBTC mints the given amount of BTC to the recipient address, directly
// in the x/bank module.
func (k Keeper) mintBTC(
	ctx sdk.Context,
	recipient sdk.AccAddress,
	amount math.Int,
) error {
	coins := sdk.NewCoins(sdk.NewCoin(evmtypes.DefaultEVMDenom, amount))

	// Mint coins to the x/bridge module account.
	err := k.bankKeeper.MintCoins(ctx, types.ModuleName, coins)
	if err != nil {
		return fmt.Errorf("failed to mint coins: %w", err)
	}

	// Send the minted coins from x/bridge module account to the final recipient.
	err = k.bankKeeper.SendCoinsFromModuleToAccount(
		ctx,
		types.ModuleName,
		recipient,
		coins,
	)
	if err != nil {
		return fmt.Errorf("failed to send coins: %w", err)
	}

	if err := k.IncreaseBTCMinted(ctx, amount); err != nil {
		return fmt.Errorf("failed to increase btc minted: %w", err)
	}

	return nil
}

// mintERC20 mints the given amount of ERC20 token to the recipient address,
// by executing a mint(address,uint256) call on the token contract.
func (k Keeper) mintERC20(
	ctx sdk.Context,
	recipient sdk.AccAddress,
	token []byte,
	amount math.Int,
) error {
	call, err := evmtypes.NewERC20MintCall(
		authtypes.NewModuleAddress(types.ModuleName).Bytes(),
		token,
		recipient.Bytes(),
		amount.BigInt(),
	)
	if err != nil {
		return fmt.Errorf("failed to create ERC20 mint call: %w", err)
	}

	_, _, err = k.evmKeeper.ExecuteContractCall(ctx, call)
	if err != nil {
		return fmt.Errorf("failed to execute ERC20 mint call: %w", err)
	}

	return nil
}

x/bridge/keeper/outflow_limit.go.content:
package keeper

import (
	"cosmossdk.io/math"
	storetypes "cosmossdk.io/store/types"
	sdk "github.com/cosmos/cosmos-sdk/types"
	"github.com/mezo-org/mezod/x/bridge/types"
	evmtypes "github.com/mezo-org/mezod/x/evm/types"
)

// OutflowResetBlocks is the number of blocks after which the outflow limit is reset.
const OutflowResetBlocks = 25000

// GetAllCurrentOutflowLimits returns all the current outflow limits.
func (k Keeper) GetAllCurrentOutflowLimits(ctx sdk.Context) []*types.CurrentOutflowLimit {
	store := ctx.KVStore(k.storeKey)

	iterator := storetypes.KVStorePrefixIterator(store, types.OutflowLimitKeyPrefix)
	defer func() {
		_ = iterator.Close()
	}()

	var out []*types.CurrentOutflowLimit

	for ; iterator.Valid(); iterator.Next() {
		token := iterator.Key()[len(types.OutflowLimitKeyPrefix):]

		var limit math.Int
		err := limit.Unmarshal(iterator.Value())
		if err != nil {
			panic(err)
		}

		out = append(
			out,
			&types.CurrentOutflowLimit{
				Token: evmtypes.BytesToHexAddress(token),
				Limit: limit,
			},
		)
	}

	return out
}

// GetAllCurrentOutflowAmounts returns all the current outflow amounts.
func (k Keeper) GetAllCurrentOutflowAmounts(ctx sdk.Context) []*types.CurrentOutflowAmount {
	store := ctx.KVStore(k.storeKey)

	iterator := storetypes.KVStorePrefixIterator(store, types.CurrentOutflowKeyPrefix)
	defer func() {
		_ = iterator.Close()
	}()

	var out []*types.CurrentOutflowAmount

	for ; iterator.Valid(); iterator.Next() {
		token := iterator.Key()[len(types.CurrentOutflowKeyPrefix):]

		var amount math.Int
		err := amount.Unmarshal(iterator.Value())
		if err != nil {
			panic(err)
		}

		out = append(
			out,
			&types.CurrentOutflowAmount{
				Token:  evmtypes.BytesToHexAddress(token),
				Amount: amount,
			},
		)
	}

	return out
}

// SetOutflowLimit sets the maximum outflow limit for a specific token.
func (k Keeper) SetOutflowLimit(
	ctx sdk.Context,
	token []byte,
	limit math.Int,
) {
	store := ctx.KVStore(k.storeKey)

	bz, err := limit.Marshal()
	if err != nil {
		panic(err)
	}

	store.Set(types.GetOutflowLimitKey(token), bz)
}

// GetOutflowLimit returns the current outflow limit for a specific token.
func (k Keeper) GetOutflowLimit(
	ctx sdk.Context,
	token []byte,
) math.Int {
	store := ctx.KVStore(k.storeKey)

	bz := store.Get(types.GetOutflowLimitKey(token))
	if len(bz) == 0 {
		return math.ZeroInt()
	}

	limit := math.ZeroInt()
	if err := limit.Unmarshal(bz); err != nil {
		panic(err)
	}

	return limit
}

// getCurrentOutflow returns the current outflow amount for a specific token.
func (k Keeper) getCurrentOutflow(
	ctx sdk.Context,
	token []byte,
) math.Int {
	store := ctx.KVStore(k.storeKey)

	bz := store.Get(types.GetCurrentOutflowKey(token))
	if len(bz) == 0 {
		return math.ZeroInt()
	}

	outflow := math.ZeroInt()
	if err := outflow.Unmarshal(bz); err != nil {
		panic(err)
	}

	return outflow
}

// increaseCurrentOutflow adds the specified amount to the current outflow for a token.
func (k Keeper) increaseCurrentOutflow(
	ctx sdk.Context,
	token []byte,
	amount math.Int,
) {
	currentOutflow := k.getCurrentOutflow(ctx, token)
	newOutflow := currentOutflow.Add(amount)

	store := ctx.KVStore(k.storeKey)

	bz, err := newOutflow.Marshal()
	if err != nil {
		panic(err)
	}

	store.Set(types.GetCurrentOutflowKey(token), bz)
}

// checkOutflowLimit verifies if adding the amount would exceed the outflow limit for a token.
func (k Keeper) checkOutflowLimit(
	ctx sdk.Context,
	token []byte,
	amount math.Int,
) error {
	capacity, _ := k.GetOutflowCapacity(ctx, token)

	if amount.GT(capacity) {
		return types.ErrOutflowLimitExceeded
	}

	return nil
}

// getLastOutflowReset returns the block height of the last outflow reset.
func (k Keeper) getLastOutflowReset(ctx sdk.Context) uint64 {
	store := ctx.KVStore(k.storeKey)
	return sdk.BigEndianToUint64(store.Get(types.LastOutflowResetKey))
}

// setLastOutflowReset sets the block height of the last outflow reset.
func (k Keeper) setLastOutflowReset(ctx sdk.Context, height uint64) {
	store := ctx.KVStore(k.storeKey)
	store.Set(types.LastOutflowResetKey, sdk.Uint64ToBigEndian(height))
}

// resetAllOutflows clears all current outflow amounts.
func (k Keeper) resetAllOutflows(ctx sdk.Context) {
	store := ctx.KVStore(k.storeKey)

	iterator := storetypes.KVStorePrefixIterator(store, types.CurrentOutflowKeyPrefix)
	defer func() {
		_ = iterator.Close()
	}()

	keys := make([][]byte, 0)
	for ; iterator.Valid(); iterator.Next() {
		keys = append(keys, iterator.Key())
	}

	// separate the deletion from the iteration
	for _, key := range keys {
		store.Delete(key)
	}
}

// GetOutflowCapacity returns the outflow capacity for a specific token
// and the capacity reset block.
func (k Keeper) GetOutflowCapacity(
	ctx sdk.Context,
	token []byte,
) (capacity math.Int, resetHeight uint64) {
	limit := k.GetOutflowLimit(ctx, token)
	current := k.getCurrentOutflow(ctx, token)
	lastReset := k.getLastOutflowReset(ctx)

	// Calculate outflow capacity (limit - current)
	capacity = limit.Sub(current)
	// Should never happen, but just in case.
	if capacity.IsNegative() {
		capacity = math.ZeroInt()
	}

	// Calculate capacity reset block (last reset + reset blocks)
	resetHeight = lastReset + OutflowResetBlocks

	return capacity, resetHeight
}

